"use strict";
// Synthetic Express-like framework (CJS). Uses http + fs + a nested dependency.
const http = require("http");
const fs = require("node:fs");
const path = require("path");
const { EventEmitter } = require("events");
const etag = require("etag-lite");

class App extends EventEmitter {
  constructor() {
    super();
    this.routes = [];
    this.env = process.env.NODE_ENV || "development";
  }
  get(route, handler) {
    this.routes.push({ method: "GET", route, handler });
    return this;
  }
  handle(req, res) {
    const url = new URL(req.url, "http://localhost");
    const hit = this.routes.find((r) => r.method === req.method && r.route === url.pathname);
    res.json = (body) => {
      const text = JSON.stringify(body);
      res.setHeader("content-type", "application/json");
      res.setHeader("etag", etag(text));
      res.end(text);
    };
    res.sendFile = (file) => {
      res.setHeader("content-type", "text/html");
      fs.createReadStream(file).pipe(res);
    };
    if (!hit) {
      res.statusCode = 404;
      return res.end("not found");
    }
    Promise.resolve(hit.handler(req, res)).catch((err) => {
      res.statusCode = 500;
      res.end(String(err && err.message));
    });
  }
  listen(port, cb) {
    // Subclassing a wrapped builtin class (spec question 2).
    class Server extends http.Server {}
    const server = new Server((req, res) => this.handle(req, res));
    server.keepAliveTimeout = 5000;
    return server.listen(port, "127.0.0.1", () => cb && cb(server));
  }
}

function createApp() {
  return new App();
}
createApp.static = (root) => (name) => path.join(root, name);
createApp.ServerClass = http.Server;
createApp.fs = fs;
module.exports = createApp;
